CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 INTEGER DEFAULT 'd', c1 INTEGER COLLATE NOCASE, c2 ANY UNIQUE, c3 ANY CHECK(c3 IS NULL OR length(c3) < 40), c4 ANY) STRICT;
INSERT OR IGNORE INTO t0(c0, c1, c2, c3, c4) VALUES(126, -289, 145, NULL, x'cb7b');
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 REAL UNIQUE, c1 ANY DEFAULT 'd', c2 INTEGER, c3 ANY COLLATE NOCASE) STRICT;
INSERT OR IGNORE INTO t1(c0, c1, c2, c3) VALUES(-7.155, 'epsilon', -476, -5);
INSERT OR IGNORE INTO t1(c0, c1, c2, c3) VALUES(-6.367, NULL, 304, x'a01c');
INSERT OR IGNORE INTO t1(c0, c1, c2, c3) VALUES(31.229, x'2a', 274, NULL);
CREATE TABLE t2(id INTEGER PRIMARY KEY, c0 TEXT COLLATE NOCASE, c1 REAL NOT NULL DEFAULT 0, c2 REAL, c3 TEXT COLLATE NOCASE, c4 TEXT DEFAULT 'd', ref INTEGER REFERENCES t1(id));
INSERT OR IGNORE INTO t2(c0, c1, c2, c3, c4, ref) VALUES(1e308, -483.7790, 4, -281, x'7f42285c2b4f', 1);
INSERT OR IGNORE INTO t2(c0, c1, c2, c3, c4, ref) VALUES(-1e308, 0, 'alpha', 633, 'omicron', NULL);
